CREATE SCHEMA identity;
CREATE SCHEMA research;
CREATE SCHEMA ops;
CREATE TABLE ops.schema_migrations(version text PRIMARY KEY, checksum text NOT NULL, applied_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE identity.principals(id uuid PRIMARY KEY, issuer text NOT NULL, subject text NOT NULL, active boolean NOT NULL DEFAULT true, can_create boolean NOT NULL DEFAULT false, UNIQUE(issuer,subject));
CREATE TABLE research.studies(id uuid PRIMARY KEY, code text NOT NULL UNIQUE, title text NOT NULL, state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','active','completed','suspended','cancelled','archived')), created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE identity.memberships(id uuid PRIMARY KEY, study_id uuid NOT NULL REFERENCES research.studies, principal_id uuid NOT NULL REFERENCES identity.principals, active boolean NOT NULL DEFAULT true, UNIQUE(study_id,principal_id), UNIQUE(study_id,id));
CREATE TABLE identity.capabilities(study_id uuid NOT NULL, membership_id uuid NOT NULL, capability text NOT NULL, revoked_at timestamptz, PRIMARY KEY(study_id,membership_id,capability), FOREIGN KEY(study_id,membership_id) REFERENCES identity.memberships(study_id,id));
CREATE TABLE research.protocol_versions(id uuid PRIMARY KEY, study_id uuid NOT NULL REFERENCES research.studies, version integer NOT NULL CHECK(version>0), config jsonb NOT NULL, hash text NOT NULL, UNIQUE(study_id,version), UNIQUE(study_id,id));
CREATE TABLE research.panelists(id uuid PRIMARY KEY, study_id uuid NOT NULL REFERENCES research.studies, group_code text NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(study_id,id));
CREATE TABLE identity.panelist_links(study_id uuid NOT NULL, membership_id uuid NOT NULL, panelist_id uuid NOT NULL, PRIMARY KEY(study_id,membership_id), UNIQUE(study_id,panelist_id), FOREIGN KEY(study_id,membership_id) REFERENCES identity.memberships(study_id,id), FOREIGN KEY(study_id,panelist_id) REFERENCES research.panelists(study_id,id));
CREATE TABLE identity.consent_versions(id uuid PRIMARY KEY, study_id uuid NOT NULL REFERENCES research.studies, locale text NOT NULL CHECK(locale IN ('de','en')), content text NOT NULL, hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(study_id,id));
CREATE TABLE identity.consents(id uuid PRIMARY KEY, study_id uuid NOT NULL, membership_id uuid NOT NULL, consent_version_id uuid NOT NULL, decision boolean NOT NULL, recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(), FOREIGN KEY(study_id,membership_id) REFERENCES identity.memberships(study_id,id), FOREIGN KEY(study_id,consent_version_id) REFERENCES identity.consent_versions(study_id,id));
CREATE TABLE research.rounds(id uuid PRIMARY KEY, study_id uuid NOT NULL REFERENCES research.studies, number integer NOT NULL CHECK(number>0), protocol_id uuid NOT NULL, consent_version_id uuid NOT NULL, state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','review','approved','open','closed','frozen','analysed','feedback_ready','released','finalized')), instrument_hash text NOT NULL, deadline timestamptz NOT NULL, closed_at timestamptz, UNIQUE(study_id,id), UNIQUE(study_id,number), FOREIGN KEY(study_id,protocol_id) REFERENCES research.protocol_versions(study_id,id), FOREIGN KEY(study_id,consent_version_id) REFERENCES identity.consent_versions(study_id,id));
CREATE TABLE research.round_items(id uuid PRIMARY KEY, study_id uuid NOT NULL, round_id uuid NOT NULL, item_code text NOT NULL, item_version integer NOT NULL CHECK(item_version>0), dimension_code text NOT NULL, scale_code text NOT NULL, texts jsonb NOT NULL, required boolean NOT NULL, display_order integer NOT NULL CHECK(display_order>0), source_ref text NOT NULL, UNIQUE(study_id,round_id,id), UNIQUE(study_id,round_id,item_code,dimension_code), FOREIGN KEY(study_id,round_id) REFERENCES research.rounds(study_id,id));
CREATE TABLE research.enrollments(id uuid PRIMARY KEY, study_id uuid NOT NULL, round_id uuid NOT NULL, panelist_id uuid NOT NULL, group_code text NOT NULL, state text NOT NULL DEFAULT 'eligible' CHECK(state IN ('eligible','in_progress','submitted','withdrawn')), UNIQUE(study_id,round_id,id), UNIQUE(study_id,round_id,panelist_id), FOREIGN KEY(study_id,round_id) REFERENCES research.rounds(study_id,id), FOREIGN KEY(study_id,panelist_id) REFERENCES research.panelists(study_id,id));
CREATE TABLE research.response_revisions(id uuid PRIMARY KEY, study_id uuid NOT NULL, round_id uuid NOT NULL, enrollment_id uuid NOT NULL, round_item_id uuid NOT NULL, revision integer NOT NULL CHECK(revision>0), status text NOT NULL CHECK(status IN ('answered','not_answered','unable_to_judge','abstained','not_applicable')), value_int integer, value_text text, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), CHECK((status='answered' AND ((value_int IS NULL)<>(value_text IS NULL))) OR (status<>'answered' AND value_int IS NULL AND value_text IS NULL)), UNIQUE(study_id,enrollment_id,round_item_id,revision), UNIQUE(study_id,round_id,enrollment_id,id), FOREIGN KEY(study_id,round_id,enrollment_id) REFERENCES research.enrollments(study_id,round_id,id), FOREIGN KEY(study_id,round_id,round_item_id) REFERENCES research.round_items(study_id,round_id,id));
CREATE TABLE research.response_current(study_id uuid NOT NULL, round_id uuid NOT NULL, enrollment_id uuid NOT NULL, round_item_id uuid NOT NULL, revision integer NOT NULL, PRIMARY KEY(study_id,enrollment_id,round_item_id), FOREIGN KEY(study_id,enrollment_id,round_item_id,revision) REFERENCES research.response_revisions(study_id,enrollment_id,round_item_id,revision), FOREIGN KEY(study_id,round_id,enrollment_id) REFERENCES research.enrollments(study_id,round_id,id), FOREIGN KEY(study_id,round_id,round_item_id) REFERENCES research.round_items(study_id,round_id,id));
CREATE TABLE research.submissions(id uuid PRIMARY KEY, study_id uuid NOT NULL, round_id uuid NOT NULL, enrollment_id uuid NOT NULL, submitted_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(study_id,enrollment_id), UNIQUE(study_id,round_id,enrollment_id,id), FOREIGN KEY(study_id,round_id,enrollment_id) REFERENCES research.enrollments(study_id,round_id,id));
CREATE TABLE research.submission_entries(study_id uuid NOT NULL, round_id uuid NOT NULL, enrollment_id uuid NOT NULL, submission_id uuid NOT NULL, response_revision_id uuid NOT NULL, PRIMARY KEY(submission_id,response_revision_id), FOREIGN KEY(study_id,round_id,enrollment_id,submission_id) REFERENCES research.submissions(study_id,round_id,enrollment_id,id), FOREIGN KEY(study_id,round_id,enrollment_id,response_revision_id) REFERENCES research.response_revisions(study_id,round_id,enrollment_id,id));
CREATE TABLE research.snapshots(id uuid PRIMARY KEY, study_id uuid NOT NULL, round_id uuid NOT NULL, content jsonb NOT NULL, hash text NOT NULL, UNIQUE(study_id,id), UNIQUE(study_id,round_id), FOREIGN KEY(study_id,round_id) REFERENCES research.rounds(study_id,id));
CREATE TABLE research.analyses(id uuid PRIMARY KEY, study_id uuid NOT NULL, snapshot_id uuid NOT NULL, content jsonb NOT NULL, hash text NOT NULL, UNIQUE(study_id,id), FOREIGN KEY(study_id,snapshot_id) REFERENCES research.snapshots(study_id,id));
CREATE TABLE research.feedback(id uuid PRIMARY KEY, study_id uuid NOT NULL, analysis_id uuid NOT NULL, content jsonb NOT NULL, hash text NOT NULL, state text NOT NULL DEFAULT 'reviewed' CHECK(state IN ('reviewed','released')), UNIQUE(study_id,id), FOREIGN KEY(study_id,analysis_id) REFERENCES research.analyses(study_id,id));
CREATE TABLE research.feedback_assignments(study_id uuid NOT NULL, round_id uuid NOT NULL, enrollment_id uuid NOT NULL, feedback_id uuid NOT NULL, PRIMARY KEY(study_id,enrollment_id), FOREIGN KEY(study_id,round_id,enrollment_id) REFERENCES research.enrollments(study_id,round_id,id), FOREIGN KEY(study_id,feedback_id) REFERENCES research.feedback(study_id,id));
CREATE TABLE research.decisions(id uuid PRIMARY KEY, study_id uuid NOT NULL, analysis_id uuid NOT NULL, item_code text NOT NULL, disposition text NOT NULL CHECK(disposition IN ('retain','revise','remove','split','merge','rerate','finalize')), reason text NOT NULL CHECK(length(reason)>0), actor_id uuid NOT NULL REFERENCES identity.principals, FOREIGN KEY(study_id,analysis_id) REFERENCES research.analyses(study_id,id));
CREATE TABLE ops.commands(study_id uuid NOT NULL REFERENCES research.studies, actor_id uuid NOT NULL REFERENCES identity.principals, command_type text NOT NULL, command_key text NOT NULL, payload_hash text NOT NULL, outcome jsonb NOT NULL, PRIMARY KEY(study_id,actor_id,command_type,command_key));
CREATE TABLE ops.audit(id uuid PRIMARY KEY, study_id uuid NOT NULL REFERENCES research.studies, actor_id uuid NOT NULL REFERENCES identity.principals, action text NOT NULL, object_ref text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE ops.jobs(id uuid PRIMARY KEY, study_id uuid NOT NULL REFERENCES research.studies, actor_id uuid NOT NULL REFERENCES identity.principals, type text NOT NULL CHECK(type IN ('analysis','export')), input_id uuid NOT NULL, state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','succeeded','retry_wait','dead_letter')), attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT clock_timestamp(), lease_until timestamptz, lease_token uuid, result_ref uuid, error_code text, UNIQUE(study_id,actor_id,type,input_id), UNIQUE(study_id,id));
CREATE TABLE ops.artifacts(id uuid PRIMARY KEY, study_id uuid NOT NULL REFERENCES research.studies, actor_id uuid NOT NULL REFERENCES identity.principals, snapshot_id uuid NOT NULL, storage_key uuid NOT NULL UNIQUE, checksum text NOT NULL, expires_at timestamptz NOT NULL, FOREIGN KEY(study_id,snapshot_id) REFERENCES research.snapshots(study_id,id));
CREATE INDEX jobs_available ON ops.jobs(state,available_at);
CREATE INDEX response_enrollment ON research.response_revisions(enrollment_id);
CREATE INDEX audit_study ON ops.audit(study_id,occurred_at);
CREATE FUNCTION ops.immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable record'; END $$;
CREATE TRIGGER immutable_protocol BEFORE UPDATE OR DELETE ON research.protocol_versions FOR EACH ROW EXECUTE FUNCTION ops.immutable();
CREATE TRIGGER immutable_revision BEFORE UPDATE OR DELETE ON research.response_revisions FOR EACH ROW EXECUTE FUNCTION ops.immutable();
CREATE TRIGGER immutable_submission BEFORE UPDATE OR DELETE ON research.submissions FOR EACH ROW EXECUTE FUNCTION ops.immutable();
CREATE TRIGGER immutable_entries BEFORE UPDATE OR DELETE ON research.submission_entries FOR EACH ROW EXECUTE FUNCTION ops.immutable();
CREATE TRIGGER immutable_snapshot BEFORE UPDATE OR DELETE ON research.snapshots FOR EACH ROW EXECUTE FUNCTION ops.immutable();
CREATE TRIGGER immutable_analysis BEFORE UPDATE OR DELETE ON research.analyses FOR EACH ROW EXECUTE FUNCTION ops.immutable();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON ops.audit FOR EACH ROW EXECUTE FUNCTION ops.immutable();
CREATE TRIGGER immutable_consent BEFORE UPDATE OR DELETE ON identity.consents FOR EACH ROW EXECUTE FUNCTION ops.immutable();
CREATE TRIGGER immutable_consent_version BEFORE UPDATE OR DELETE ON identity.consent_versions FOR EACH ROW EXECUTE FUNCTION ops.immutable();
CREATE FUNCTION ops.protect_instrument() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE rid uuid; sid uuid; st text;
BEGIN
 IF TG_OP='DELETE' THEN rid:=OLD.round_id; sid:=OLD.study_id; ELSE rid:=NEW.round_id; sid:=NEW.study_id; END IF;
 SELECT state INTO st FROM research.rounds WHERE id=rid AND study_id=sid FOR SHARE;
 IF st<>'draft' THEN RAISE EXCEPTION 'instrument locked'; END IF;
 IF TG_OP='UPDATE' AND (NEW.round_id<>OLD.round_id OR NEW.study_id<>OLD.study_id) THEN RAISE EXCEPTION 'instrument move forbidden'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;
CREATE TRIGGER instrument_locked BEFORE INSERT OR UPDATE OR DELETE ON research.round_items FOR EACH ROW EXECUTE FUNCTION ops.protect_instrument();
CREATE FUNCTION ops.protect_feedback() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.state='released' THEN RAISE EXCEPTION 'feedback locked'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $$;
CREATE TRIGGER feedback_locked BEFORE UPDATE OR DELETE ON research.feedback FOR EACH ROW EXECUTE FUNCTION ops.protect_feedback();
